    indegree = {}
    adjacency = {}

    for node in nodes:
        indegree[node] = 0
        adjacency[node] = set()

    for u, v in edges:
        if u not in adjacency or v not in indegree:
            raise ValueError
        if v not in adjacency[u]:
            adjacency[u].add(v)
            indegree[v] += 1

    available = [node for node in nodes if indegree[node] == 0]

    size = len(available)
    i = size // 2 - 1
    while i >= 0:
        j = i
        while True:
            left = 2 * j + 1
            right = left + 1
            smallest = j

            if left < size and available[left] < available[smallest]:
                smallest = left
            if right < size and available[right] < available[smallest]:
                smallest = right

            if smallest == j:
                break

            available[j], available[smallest] = available[smallest], available[j]
            j = smallest

        i -= 1

    result = []

    while available:
        node = available[0]
        result.append(node)

        last = available.pop()
        if available:
            available[0] = last
            i = 0
            size = len(available)

            while True:
                left = 2 * i + 1
                right = left + 1
                smallest = i

                if left < size and available[left] < available[smallest]:
                    smallest = left
                if right < size and available[right] < available[smallest]:
                    smallest = right

                if smallest == i:
                    break

                available[i], available[smallest] = available[smallest], available[i]
                i = smallest

        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                available.append(neighbor)
