def edit_distance(a: str, b: str) -> int:
    if len(a) < len(b):
        a, b = b, a

    n = len(b)
    if n == 0:
        return len(a)

    prev = list(range(n + 1))
    curr = [0] * (n + 1)

    for i in range(1, len(a) + 1):
        curr[0] = i

        for j in range(1, n + 1):
            delete = prev[j] + 1
            insert = curr[j - 1] + 1
            substitute = prev[j - 1] + (0 if a[i - 1] == b[j - 1] else 1)

            best = delete
            if insert < best:
                best = insert
            if substitute < best:
                best = substitute

            curr[j] = best

        prev, curr = curr, prev

    return prev[n]
