def schedule_profit(jobs: list[tuple[int, int, int]]) -> int:
    ordered = sorted((job[1], job[0], job[2]) for job in jobs)
    n = len(ordered)
    dp = [0] * (n + 1)

    for i in range(n):
        start = ordered[i][1]
        profit = ordered[i][2]

        lo = 0
        hi = i
        while lo < hi:
            mid = (lo + hi) // 2
            if ordered[mid][0] <= start:
                lo = mid + 1
            else:
                hi = mid

        chosen = dp[lo] + profit
        if chosen > dp[i]:
            dp[i + 1] = chosen
        else:
            dp[i + 1] = dp[i]

    return dp[n]
